INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4245313, 611378, 39850, '<td valign="top">First true one (my interpretations anyway) I''ve come across.  Difficult challenge this one.  I think what you''ve captured does enhance the image.  Nice and sharp on your subject too.  Difficult, but maybe less at the top which detracts from the simplicity of the bottom of the image and the good bokeh.</td>', 'First true one (my interpretations anyway) I''ve come across.  Difficult challenge this one.  I think what you''ve captured does enhance the image.  Nice and sharp on your subject too.  Difficult, but maybe less at the top which detracts from the simplicity of the bottom of the image and the good bokeh.', '2007-11-14 00:14:55.000000', NULL, 1),
(4245325, 613097, 39850, '<td valign="top">Good use of fore bokeh (difficult challenge).  I think if the model''s face and clothing were softer may have made this a stronger image.</td>', 'Good use of fore bokeh (difficult challenge).  I think if the model''s face and clothing were softer may have made this a stronger image.', '2007-11-14 00:16:56.000000', NULL, 1),
(4245338, 610668, 39850, '<td valign="top">7 - Excellent perspective and nice use of fore bokeh (difficult challenge).  With this composition and symmetry (which I think is excellent), very difficult, but for this challenge would like to have seen the fore bokeh ''stronger'' somehow.  Nice image anyway and really like the green.  Difficult (just to use that word again), but there seems to be some slight gamma/something issues in and around the blacks, but could be my monitor.</td>', '7 - Excellent perspective and nice use of fore bokeh (difficult challenge).  With this composition and symmetry (which I think is excellent), very difficult, but for this challenge would like to have seen the fore bokeh ''stronger'' somehow.  Nice image anyway and really like the green.  Difficult (just to use that word again), but there seems to be some slight gamma/something issues in and around the blacks, but could be my monitor.', '2007-11-14 00:19:07.000000', NULL, 1),
(4245346, 612929, 39850, '<td valign="top">You must have been low to get this.  Nice fore bokeh, difficult challenge - like to have seen even more, ''somehow'' but.. not easy.</td>', 'You must have been low to get this.  Nice fore bokeh, difficult challenge - like to have seen even more, ''somehow'' but.. not easy.', '2007-11-14 00:20:32.000000', NULL, 1),
(4245355, 611073, 39850, '<td valign="top">Like your crop and how you''ve used the bokeh as a frame.  Difficult, but like to have seen the bokeh a little ''softer''.</td>', 'Like your crop and how you''ve used the bokeh as a frame.  Difficult, but like to have seen the bokeh a little ''softer''.', '2007-11-14 00:22:46.000000', NULL, 1),
(4245361, 611656, 39850, '<td valign="top">Nice image.  Difficult, but like to have seen the bokeh a little stronger - think you did well to capture ''both types'' of bokeh though - I know how difficult this is.  Colors are nice.  Perhaps a tighter crop at the bottom may have enhanced the fore bokeh and made it a stronger image for this challenge, not sure.</td>', 'Nice image.  Difficult, but like to have seen the bokeh a little stronger - think you did well to capture ''both types'' of bokeh though - I know how difficult this is.  Colors are nice.  Perhaps a tighter crop at the bottom may have enhanced the fore bokeh and made it a stronger image for this challenge, not sure.', '2007-11-14 00:24:53.000000', NULL, 1),
(4245365, 613014, 39850, '<td valign="top">I''m struggling to see any <i>fore</i> bokeh in this.</td>', 'I''m struggling to see any fore bokeh in this.', '2007-11-14 00:26:09.000000', NULL, 1),
(4245395, 613002, 84150, '<td valign="top">some really good background bokeh...</td>', 'some really good background bokeh...', '2007-11-14 00:32:47.000000', NULL, 1),
(4245397, 611690, 84150, '<td valign="top">I don''t know if this meets the challenge, but the portrait is beautiful. 7</td>', 'I don''t know if this meets the challenge, but the portrait is beautiful. 7', '2007-11-14 00:33:59.000000', NULL, 1),
(4245405, 612423, 61818, '<td valign="top">I''m all for boob shots but you really, really need to practice lighting.</td>', 'I''m all for boob shots but you really, really need to practice lighting.', '2007-11-14 00:36:45.000000', NULL, 1),
(4245406, 610006, 39427, '<td valign="top">wow thats a cool effect, truly.  I do wish tho that the ''in focus'' part of the picture was composed somewhat differently, it feels weird off to the side like that.  Still, 8 for originality</td>', 'wow thats a cool effect, truly.  I do wish tho that the ''in focus'' part of the picture was composed somewhat differently, it feels weird off to the side like that.  Still, 8 for originality', '2007-11-14 00:37:22.000000', NULL, 1),
(4245414, 611427, 61818, '<td valign="top">You should buy bottled soap in a dispenser.  That bar of soap sitting in the tray is a bacteria magnet getting blasted by fecal clouds every time you flush the toilet.  Seriously, read up on it.  You wouldn''t want to be responsible for this guy''s arm getting infected would you?</td>', 'You should buy bottled soap in a dispenser.  That bar of soap sitting in the tray is a bacteria magnet getting blasted by fecal clouds every time you flush the toilet.  Seriously, read up on it.  You wouldn''t want to be responsible for this guy''s arm getting infected would you?', '2007-11-14 00:40:00.000000', NULL, 1),
(4245418, 610327, 71179, '<td valign="top">i like this photo, but you didn''t follow the theme.</td>', 'i like this photo, but you didn''t follow the theme.', '2007-11-14 00:41:05.000000', NULL, 1),
(4245429, 610398, 39850, '<td valign="top">7 - Nice use of fore bokeh in this difficult challenge.  Like to have seen it a little stronger, but again ''difficult''.  Fairly minor but the white ''dot'' in the background detracts slightly, so perhaps cropping that out may have made the image stronger.  Nice colorings.</td>', '7 - Nice use of fore bokeh in this difficult challenge.  Like to have seen it a little stronger, but again ''difficult''.  Fairly minor but the white ''dot'' in the background detracts slightly, so perhaps cropping that out may have made the image stronger.  Nice colorings.', '2007-11-14 00:46:31.000000', NULL, 1),
(4245432, 610717, 39850, '<td valign="top">Very painterly.  Nice image, just wish there was a little more room to the left.</td>', 'Very painterly.  Nice image, just wish there was a little more room to the left.', '2007-11-14 00:47:46.000000', NULL, 1),
(4245437, 612783, 39850, '<td valign="top">7 - Oh, that''s nice.  I know how difficult this is as I tried it.  Nice focus on the spider whilst retaining good fore bokeh of both kinds.  Spider does get a little lost in all the white, but I''m sure tweaking curves/contrast was also difficult.</td>', '7 - Oh, that''s nice.  I know how difficult this is as I tried it.  Nice focus on the spider whilst retaining good fore bokeh of both kinds.  Spider does get a little lost in all the white, but I''m sure tweaking curves/contrast was also difficult.', '2007-11-14 00:50:37.000000', NULL, 1),
(4245440, 611008, 39850, '<td valign="top">Nice set up.  Shame more of the ''fore flowers'' couldn''t have been included in the frame.</td>', 'Nice set up.  Shame more of the ''fore flowers'' couldn''t have been included in the frame.', '2007-11-14 00:51:43.000000', NULL, 1),
(4245443, 612790, 39850, '<td valign="top">Nice idea.  A little more light play and sharper on the focal point would have made a stronger image in my opinion.  Good use of fore bokeh.</td>', 'Nice idea.  A little more light play and sharper on the focal point would have made a stronger image in my opinion.  Good use of fore bokeh.', '2007-11-14 00:52:29.000000', NULL, 1),
