(4246527, 612790, 57936, '<td valign="top">It looks like the bokeh extends to the end of the frame. Interesting abstract image, but it needs focus to have FOREGROUND bokeh.</td>', 'It looks like the bokeh extends to the end of the frame. Interesting abstract image, but it needs focus to have FOREGROUND bokeh.', '2007-11-14 10:43:16.000000', NULL, 1),
(4246528, 612528, 23484, '<td valign="top">Very nicely composed shot. The candles are very effective.</td>', 'Very nicely composed shot. The candles are very effective.', '2007-11-14 10:43:26.000000', NULL, 1),
(4246530, 612921, 23484, '<td valign="top">Really had to look close to see it.</td>', 'Really had to look close to see it.', '2007-11-14 10:44:10.000000', NULL, 1),
(4246532, 612472, 57936, '<td valign="top">A bit dark and the cardinal is a bit too central in the image, but very pretty.</td>', 'A bit dark and the cardinal is a bit too central in the image, but very pretty.', '2007-11-14 10:44:20.000000', NULL, 1),
(4246537, 613051, 57936, '<td valign="top">This is too dark to see the foreground bokey. Also, the entire table seems in focus, which extends to the front of the frame, leaving very little room for foreground bokeh...</td>', 'This is too dark to see the foreground bokey. Also, the entire table seems in focus, which extends to the front of the frame, leaving very little room for foreground bokeh...', '2007-11-14 10:46:13.000000', NULL, 1),
(4246540, 612939, 23484, '<td valign="top">I really like this. Gives the feeling that it skated in from out of nowhere.</td>', 'I really like this. Gives the feeling that it skated in from out of nowhere.', '2007-11-14 10:46:50.000000', NULL, 1),
(4246541, 610471, 57936, '<td valign="top">Wonderfully done! Bravo!!! 10</td>', 'Wonderfully done! Bravo!!! 10', '2007-11-14 10:46:50.000000', NULL, 1),
(4246542, 610891, 23484, '<td valign="top">Good job on the idea and execution. Nice soft colors too.</td>', 'Good job on the idea and execution. Nice soft colors too.', '2007-11-14 10:47:31.000000', NULL, 1),
(4246545, 613056, 23484, '<td valign="top">Nice job. I like the diagonal also. I''m surprised you didn''t use the 8 ball.</td>', 'Nice job. I like the diagonal also. I''m surprised you didn''t use the 8 ball.', '2007-11-14 10:49:06.000000', NULL, 1),
(4246548, 612513, 57936, '<td valign="top">I don''t really see much bokeh here. Some of the hearts look a bit blurry, but not really in a bokeh fashion. They also look pasted on. I expect they are on a mirror, but it looks like they could be drop-ins, which is a no-no for Basic Editing...</td>', 'I don''t really see much bokeh here. Some of the hearts look a bit blurry, but not really in a bokeh fashion. They also look pasted on. I expect they are on a mirror, but it looks like they could be drop-ins, which is a no-no for Basic Editing...', '2007-11-14 10:50:07.000000', NULL, 1),
(4246549, 612974, 23484, '<td valign="top">This seems backwards from the challenge description.</td>', 'This seems backwards from the challenge description.', '2007-11-14 10:50:41.000000', NULL, 1),
(4246553, 611385, 23484, '<td valign="top">Nice job. I like the dark colors.</td>', 'Nice job. I like the dark colors.', '2007-11-14 10:51:22.000000', NULL, 1),
(4246555, 612371, 23484, '<td valign="top">The whole image seems too washed out.</td>', 'The whole image seems too washed out.', '2007-11-14 10:51:41.000000', NULL, 1),
(4246561, 610951, 23484, '<td valign="top">Very nicely composed and meets the challenge well.</td>', 'Very nicely composed and meets the challenge well.', '2007-11-14 10:53:14.000000', NULL, 1),
(4246562, 612660, 57936, '<td valign="top">This could use to be straightened. I would think that the roof of the building and the silo would be straight even if the area is hilly. Also, the long DOF for the rest of the picture with the blur close up doesn''t make for effective foreground bokeh, it just looks like you should have moved to a better spot.</td>', 'This could use to be straightened. I would think that the roof of the building and the silo would be straight even if the area is hilly. Also, the long DOF for the rest of the picture with the blur close up doesn''t make for effective foreground bokeh, it just looks like you should have moved to a better spot.', '2007-11-14 10:53:33.000000', NULL, 1),
(4246569, 612365, 57936, '<td valign="top">Hard to say what is foreground in this image, with the top-down view and the center of the image in focus, it looks like that is the "foreground" here.</td>', 'Hard to say what is foreground in this image, with the top-down view and the center of the image in focus, it looks like that is the "foreground" here.', '2007-11-14 10:54:47.000000', NULL, 1),
(4246571, 610327, 69102, '<td valign="top">very cool picture, but all the unfocused parts are in the background</td>', 'very cool picture, but all the unfocused parts are in the background', '2007-11-14 10:55:05.000000', NULL, 1),
(4246572, 611507, 23484, '<td valign="top">Seems like nothing is in focus.</td>', 'Seems like nothing is in focus.', '2007-11-14 10:55:14.000000', NULL, 1),
(4246575, 613013, 23484, '<td valign="top">Good job, nice B&amp;W with good detail.</td>', 'Good job, nice B&W with good detail.', '2007-11-14 10:55:45.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(4246576, 611385, 57936, '<td valign="top">This would get a higher score if the chess board was level.</td>', 'This would get a higher score if the chess board was level.', '2007-11-14 10:55:50.000000', NULL, 1),
(4246586, 611794, 57936, '<td valign="top">With the long DOF for the rest of the picture the blurry leaves just look like mistakes or distractions intead of "Foreground" bokeh. This would be really nice without the leaves though! 5.</td>', 'With the long DOF for the rest of the picture the blurry leaves just look like mistakes or distractions intead of "Foreground" bokeh. This would be really nice without the leaves though! 5.', '2007-11-14 10:57:20.000000', NULL, 1),
(4246589, 613014, 57936, '<td valign="top">I don''t see much bokeh here at all. DNMC</td>', 'I don''t see much bokeh here at all. DNMC', '2007-11-14 10:57:59.000000', NULL, 1),
(4246600, 611542, 63398, '<td valign="top">I think this is pretty well done, and unlike others, I don''t think that the fade-off in the distance negates the foreground effect. Good composition and detail where it needs to be. 7</td>', 'I think this is pretty well done, and unlike others, I don''t think that the fade-off in the distance negates the foreground effect. Good composition and detail where it needs to be. 7', '2007-11-14 10:59:59.000000', NULL, 1),
(4246604, 611010, 23484, '<td valign="top">Nice shot with really good detail. Nice sharp colors.</td>', 'Nice shot with really good detail. Nice sharp colors.', '2007-11-14 11:00:45.000000', NULL, 1),
(4246606, 612954, 63398, '<td valign="top">Nicely done, IMO, terrific subject, too!.....8&gt;) What a face!!!!! I like the background Bokeh very much. 7</td>', 'Nicely done, IMO, terrific subject, too!.....8>) What a face!!!!! I like the background Bokeh very much. 7', '2007-11-14 11:01:31.000000', NULL, 1),
(4246608, 610001, 13390, '<td valign="top">No foreground bokeh, or any background bokeh.</td>', 'No foreground bokeh, or any background bokeh.', '2007-11-14 11:01:44.000000', NULL, 1),
(4246615, 613078, 63398, '<td valign="top">Very nice, good framing and the Bokeh is distinct, yet unobtrusive. 7</td>', 'Very nice, good framing and the Bokeh is distinct, yet unobtrusive. 7', '2007-11-14 11:02:40.000000', NULL, 1),
(4246625, 612915, 13390, '<td valign="top">Not as clear as I would like, it may have done better in a smaller crop with the back box sharper and no wrinkles in the sheet.</td>', 'Not as clear as I would like, it may have done better in a smaller crop with the back box sharper and no wrinkles in the sheet.', '2007-11-14 11:05:14.000000', NULL, 1),
(4246633, 612966, 13390, '<td valign="top">I can tell you were trying to use the grass as the foreground bokeh, but there isn''t enough to make an impact on the picture</td>', 'I can tell you were trying to use the grass as the foreground bokeh, but there isn''t enough to make an impact on the picture', '2007-11-14 11:06:53.000000', NULL, 1),
(4246637, 611561, 85384, '<td valign="top">cool eagle, but the bokeh foreground is just there, doesn''t add anything to the picture.</td>', 'cool eagle, but the bokeh foreground is just there, doesn''t add anything to the picture.', '2007-11-14 11:07:54.000000', NULL, 1),
(4246639, 611487, 13390, '<td valign="top">Watch the overexposure</td>', 'Watch the overexposure', '2007-11-14 11:08:48.000000', NULL, 1),
(4246647, 611532, 85384, '<td valign="top">too much bokeh, i think it takes away from the bird....</td>', 'too much bokeh, i think it takes away from the bird....', '2007-11-14 11:10:03.000000', NULL, 1),
(4246650, 612914, 85384, '<td valign="top">gotta say DNMC i mean the monkey is a bit out of focus</td>', 'gotta say DNMC i mean the monkey is a bit out of focus', '2007-11-14 11:11:02.000000', NULL, 1),
(4246651, 611379, 57936, '<td valign="top">With only the foreground bystander out of focus and long DOF for the rest of the shot this doesn''t look like intentional foreground bokeh for an effect but more like the photographer should have moved over two steps to the left.</td>', 'With only the foreground bystander out of focus and long DOF for the rest of the shot this doesn''t look like intentional foreground bokeh for an effect but more like the photographer should have moved over two steps to the left.', '2007-11-14 11:11:13.000000', NULL, 1),
(4246652, 610327, 85384, '<td valign="top">DNMC</td>', 'DNMC', '2007-11-14 11:11:16.000000', NULL, 1),
(4246653, 612783, 85384, '<td valign="top">focus fault</td>', 'focus fault', '2007-11-14 11:11:23.000000', NULL, 1),
(4246654, 610372, 85384, '<td valign="top">i feel the bokeh is the "subject" of this photo... rather than making the photo better...</td>', 'i feel the bokeh is the "subject" of this photo... rather than making the photo better...', '2007-11-14 11:12:03.000000', NULL, 1),
(4246657, 612947, 85384, '<td valign="top">bokeh in foreground?</td>', 'bokeh in foreground?', '2007-11-14 11:12:07.000000', NULL, 1),
(4246659, 610222, 85384, '<td valign="top">cool picture ....</td>', 'cool picture ....', '2007-11-14 11:13:22.000000', NULL, 1),
(4246662, 611385, 85384, '<td valign="top">dark</td>', 'dark', '2007-11-14 11:13:45.000000', NULL, 1),
(4246663, 612435, 57936, '<td valign="top">This looks like a long DOF shot. There is no obvious bokeh. Also, the top right is entirely too blown-out, the gazebo and horizon are not straight, and the gazebo is cut-off on the right site. 1</td>', 'This looks like a long DOF shot. There is no obvious bokeh. Also, the top right is entirely too blown-out, the gazebo and horizon are not straight, and the gazebo is cut-off on the right site. 1', '2007-11-14 11:14:04.000000', NULL, 1),
(4246666, 612423, 57936, '<td valign="top">too dark to see the foreground bokeh effectively.</td>', 'too dark to see the foreground bokeh effectively.', '2007-11-14 11:14:42.000000', NULL, 1),
(4246677, 610891, 31535, '<td valign="top">Very nice idea, although I do have a few problems with it. The crop to the right of the cross is a little too close. It also looks to me like it leans to the right where as the bible in the background is off kilter to the left.</td>', 'Very nice idea, although I do have a few problems with it. The crop to the right of the cross is a little too close. It also looks to me like it leans to the right where as the bible in the background is off kilter to the left.', '2007-11-14 11:17:24.000000', NULL, 1),
(4246701, 612472, 63398, '<td valign="top">Very nicely done! Thois should suit the Bokeh police, too! LOL!!! 7</td>', 'Very nicely done! Thois should suit the Bokeh police, too! LOL!!! 7', '2007-11-14 11:27:01.000000', NULL, 1),
(4246707, 611010, 65234, '<td valign="top">Very cute idea.</td>', 'Very cute idea.', '2007-11-14 11:29:17.000000', NULL, 1),
(4246709, 612604, 65234, '<td valign="top">Leaves frame the subject nicely.  Might prefer a tighter crop to the right and bottom to better bring out the subject, since his clothes blend into the background trees quite a bit and the color on the right distracts.</td>', 'Leaves frame the subject nicely.  Might prefer a tighter crop to the right and bottom to better bring out the subject, since his clothes blend into the background trees quite a bit and the color on the right distracts.', '2007-11-14 11:31:30.000000', NULL, 1),
(4246714, 612977, 65234, '<td valign="top">The Mars company must have had a nice blip in sales last week.  Like the idea; might prefer the focal candy more on the rule of thirds, and there''s a distinct red/orange glow above it that a slightly different angle might eliminate.</td>', 'The Mars company must have had a nice blip in sales last week.  Like the idea; might prefer the focal candy more on the rule of thirds, and there''s a distinct red/orange glow above it that a slightly different angle might eliminate.', '2007-11-14 11:35:08.000000', NULL, 1),
(4246723, 613064, 65234, '<td valign="top">OK.  Not blowing me away, but OK.  A tighter crop on just that right window with the branches and bokeh making interesting patterns might be fun to play with.</td>', 'OK.  Not blowing me away, but OK.  A tighter crop on just that right window with the branches and bokeh making interesting patterns might be fun to play with.', '2007-11-14 11:40:03.000000', NULL, 1),
(4246726, 612919, 65234, '<td valign="top">Flag in the foreground does add impact.  I would crop much tighter on the top and bottom to eliminate extraneous background, and maybe try for a sharper focus on the wreath.</td>', 'Flag in the foreground does add impact.  I would crop much tighter on the top and bottom to eliminate extraneous background, and maybe try for a sharper focus on the wreath.', '2007-11-14 11:41:38.000000', NULL, 1),
(4246731, 613097, 23484, '<td valign="top">Nice job. I like the Contrast with the B&amp;W.</td>', 'Nice job. I like the Contrast with the B&W.', '2007-11-14 11:44:44.000000', NULL, 1),
(4246733, 612630, 31829, '<td valign="top">There''s good bokeh and there''s bad bokeh.  Unfortunately, this is both. ;-)  Let me explain.  You have a nice smooth out-of-focus area on the right here, however it''s a distraction for this type of photography and takes away from the action on the field.</td>', 'There''s good bokeh and there''s bad bokeh.  Unfortunately, this is both. ;-)  Let me explain.  You have a nice smooth out-of-focus area on the right here, however it''s a distraction for this type of photography and takes away from the action on the field.', '2007-11-14 11:45:05.000000', NULL, 1),
(4246734, 610752, 65234, '<td valign="top">Pretty nice clumps of ''shrooms you found, and the foreground leaves of grass are a nice echo of the sharper ones near the subject.  I think the amount of foreground is a little overwhelming to them, though.  You could crop quite a bit off the bottom and some from the right and bring out the diagonal in the composition more strongly, as well as making the main mushrooms fall more on a rule of thirds line.</td>', 'Pretty nice clumps of ''shrooms you found, and the foreground leaves of grass are a nice echo of the sharper ones near the subject.  I think the amount of foreground is a little overwhelming to them, though.  You could crop quite a bit off the bottom and some from the right and bring out the diagonal in the composition more strongly, as well as making the main mushrooms fall more on a rule of thirds line.', '2007-11-14 11:45:14.000000', NULL, 1),
(4246736, 612947, 23484, '<td valign="top">Really cool shot. I love the processing and the bright color of the leaf. 8</td>', 'Really cool shot. I love the processing and the bright color of the leaf. 8', '2007-11-14 11:45:44.000000', NULL, 1),
(4246739, 612528, 65234, '<td valign="top">Nice composition and nice use of foreground bokeh (and some pretty bokeh in the back, too).  Very much like the shadow of the cross on his cheek.</td>', 'Nice composition and nice use of foreground bokeh (and some pretty bokeh in the back, too).  Very much like the shadow of the cross on his cheek.', '2007-11-14 11:46:28.000000', NULL, 1),
(4246743, 612848, 23484, '<td valign="top">I like the old beat up baseball. Nice idea. It seems a little too much centered but still very nice shot. 7</td>', 'I like the old beat up baseball. Nice idea. It seems a little too much centered but still very nice shot. 7', '2007-11-14 11:47:32.000000', NULL, 1),
(4246747, 612457, 31829, '<td valign="top">There''s no Foreground Bokeh here...</td>', 'There''s no Foreground Bokeh here...', '2007-11-14 11:48:17.000000', NULL, 1),
(4246748, 612414, 23484, '<td valign="top">Well framed subject. Nice color matching.</td>', 'Well framed subject. Nice color matching.', '2007-11-14 11:48:28.000000', NULL, 1),
(4246753, 612365, 65234, '<td valign="top">Nice detail on the flwoer.  I''m seeing sharp focus in the center and gradually less focus going outward, so I will presume the petals are coming toward me and thus are in the foreground.  The darker spots on the petals do add a nice bit of dimension to the composition.</td>', 'Nice detail on the flwoer.  I''m seeing sharp focus in the center and gradually less focus going outward, so I will presume the petals are coming toward me and thus are in the foreground.  The darker spots on the petals do add a nice bit of dimension to the composition.', '2007-11-14 11:49:44.000000', NULL, 1),
(4246755, 610327, 31829, '<td valign="top">Eh...where''s the foreground Bokeh here?</td>', 'Eh...where''s the foreground Bokeh here?', '2007-11-14 11:50:24.000000', NULL, 1),
(4246760, 612787, 65234, '<td valign="top">That does not look like a happy dog.  The focus on the eyes is nice though they could use a tad more light to really bring them out.  Not really feeling that the OOF foreground is adding a lot, but it isn''t detracting, either.</td>', 'That does not look like a happy dog.  The focus on the eyes is nice though they could use a tad more light to really bring them out.  Not really feeling that the OOF foreground is adding a lot, but it isn''t detracting, either.', '2007-11-14 11:52:01.000000', NULL, 1),
(4246767, 613019, 52472, '<td valign="top">I know it''s asked a lot and quite dangerous to remove, but the spider-web is distracting... Anyway, it''s a great picture, I like the lighting.</td>', 'I know it''s asked a lot and quite dangerous to remove, but the spider-web is distracting... Anyway, it''s a great picture, I like the lighting.', '2007-11-14 11:53:31.000000', NULL, 1),
(4246769, 611427, 63398, '<td valign="top">Grim.....good composition on the glass and positioning. Edgy and uncomfortable shot for me. 6</td>', 'Grim.....good composition on the glass and positioning. Edgy and uncomfortable shot for me. 6', '2007-11-14 11:54:22.000000', NULL, 1),
(4246776, 612790, 23484, '<td valign="top">Very interesting abstract shot. Very unique choice.</td>', 'Very interesting abstract shot. Very unique choice.', '2007-11-14 11:55:27.000000', NULL, 1),
(4246778, 610687, 23484, '<td valign="top">Nice portrait shot. Love the soft color.</td>', 'Nice portrait shot. Love the soft color.', '2007-11-14 11:56:01.000000', NULL, 1),
(4246786, 612714, 65234, '<td valign="top">Leaves are pretty much framing the hawk.  Wish the sky weren''t so drab but I''m sure the hawk wasn''t going to wait around for a better-looking background.</td>', 'Leaves are pretty much framing the hawk.  Wish the sky weren''t so drab but I''m sure the hawk wasn''t going to wait around for a better-looking background.', '2007-11-14 11:57:45.000000', NULL, 1),
(4246793, 613019, 65234, '<td valign="top">Nice one!  I like the lit-up spines in the foreground echoing the sharp ones on the subject.  I would increase the saturation and contrast a bit to really give this depth, but it is nice as is.</td>', 'Nice one!  I like the lit-up spines in the foreground echoing the sharp ones on the subject.  I would increase the saturation and contrast a bit to really give this depth, but it is nice as is.', '2007-11-14 12:00:01.000000', NULL, 1),
(4246797, 612434, 65234, '<td valign="top">Pretty in an abstract way. The tilt of the candle is a little disconcerting to me.</td>', 'Pretty in an abstract way. The tilt of the candle is a little disconcerting to me.', '2007-11-14 12:00:52.000000', NULL, 1),
(4246798, 612919, 63398, '<td valign="top">Excellent job! 7</td>', 'Excellent job! 7', '2007-11-14 12:01:13.000000', NULL, 1),
(4246808, 610589, 65234, '<td valign="top">Much bokeh!  I like the diagonal composition and colors.  I kind of feel like there''s motion everywhere but the main focal point, which may make me go look for the dramamine ;-)</td>', 'Much bokeh!  I like the diagonal composition and colors.  I kind of feel like there''s motion everywhere but the main focal point, which may make me go look for the dramamine ;-)', '2007-11-14 12:05:52.000000', NULL, 1),
(4246812, 611794, 65234, '<td valign="top">Love those bright red trees.  Leaves in the foreground emphasize the season nicely.</td>', 'Love those bright red trees.  Leaves in the foreground emphasize the season nicely.', '2007-11-14 12:07:04.000000', NULL, 1),
(4246813, 612764, 63398, '<td valign="top">Very well done! Challenge perfectly met IMO!!! 7</td>', 'Very well done! Challenge perfectly met IMO!!! 7', '2007-11-14 12:07:06.000000', NULL, 1),
(4246814, 612416, 65234, '<td valign="top">Not quite sure if the bokeh enhances or detracts.  If her eyes matched one of the foreground colors this might work for me, but as is I think the foreground is overpowering the model.</td>', 'Not quite sure if the bokeh enhances or detracts.  If her eyes matched one of the foreground colors this might work for me, but as is I think the foreground is overpowering the model.', '2007-11-14 12:08:35.000000', NULL, 1),
(4246815, 610589, 23484, '<td valign="top">Normally, I wouldn''t have scored this very high but it has such a neat effect. I really like it. 8</td>', 'Normally, I wouldn''t have scored this very high but it has such a neat effect. I really like it. 8', '2007-11-14 12:08:36.000000', NULL, 1),
(4246817, 612412, 63398, '<td valign="top">*In My Opinion* you missed the mark with the DOF being too shallow to cover the foreground Bokeh effectively. 4</td>', '*In My Opinion* you missed the mark with the DOF being too shallow to cover the foreground Bokeh effectively. 4', '2007-11-14 12:08:52.000000', NULL, 1),
(4246818, 611197, 23484, '<td valign="top">Nice different unique idea.</td>', 'Nice different unique idea.', '2007-11-14 12:09:02.000000', NULL, 1),
(4246826, 612561, 63398, '<td valign="top">Excellent job! Very pretty! Great composition! 7</td>', 'Excellent job! Very pretty! Great composition! 7', '2007-11-14 12:11:08.000000', NULL, 1),
(4246828, 612811, 65234, '<td valign="top">Nasal bokeh!  Something different :-)</td>', 'Nasal bokeh!  Something different :-)', '2007-11-14 12:11:59.000000', NULL, 1),
(4246829, 612477, 63398, '<td valign="top">Not bad, but I would have liked to have seen a larger portion of the image with the cleanly focused subject. That''s just my take, though.....8&gt;) 5</td>', 'Not bad, but I would have liked to have seen a larger portion of the image with the cleanly focused subject. That''s just my take, though.....8>) 5', '2007-11-14 12:12:25.000000', NULL, 1),
(4246830, 612840, 65234, '<td valign="top">Composition, colors and DOF are great.  A few drops of water catching the light on the big petals in the foreground and this would rank very high IMO.</td>', 'Composition, colors and DOF are great.  A few drops of water catching the light on the big petals in the foreground and this would rank very high IMO.', '2007-11-14 12:13:22.000000', NULL, 1),
(4246838, 612630, 36981, '<td valign="top">I feel that the foreground bokeh in this image actually detracts from the picture, because it seems just to be a sleeve of a bystander that got into the frame by accident.  Perhaps I''m wrong and there''s more significance to it ...</td>', 'I feel that the foreground bokeh in this image actually detracts from the picture, because it seems just to be a sleeve of a bystander that got into the frame by accident.  Perhaps I''m wrong and there''s more significance to it ...', '2007-11-14 12:15:30.000000', NULL, 1),
(4246843, 613098, 63398, '<td valign="top">That''s really sweet!!!! I love how your Bokeh is "Naught but a Whisper!". A fine entry, IMO......9</td>', 'That''s really sweet!!!! I love how your Bokeh is "Naught but a Whisper!". A fine entry, IMO......9', '2007-11-14 12:16:50.000000', NULL, 1),
(4246848, 612915, 65234, '<td valign="top">The bokeh looks like little eyeballs on each piece of candy.  And they''re coming at me.  I am now officially weirded out by this image!  Extra point for triggering my imagination to run wild.  (note - iron your background cloth next time and make your focal point sharper)</td>', 'The bokeh looks like little eyeballs on each piece of candy.  And they''re coming at me.  I am now officially weirded out by this image!  Extra point for triggering my imagination to run wild.  (note - iron your background cloth next time and make your focal point sharper)', '2007-11-14 12:19:32.000000', NULL, 1),
(4246849, 612371, 63398, '<td valign="top">This one doesn''t quite make it for me. I don''t know if this is through some fiber/material, but I can''t define it so it just doesn''t work for me.....sorry....4</td>', 'This one doesn''t quite make it for me. I don''t know if this is through some fiber/material, but I can''t define it so it just doesn''t work for me.....sorry....4', '2007-11-14 12:19:36.000000', NULL, 1),
(4246868, 612782, 63398, '<td valign="top">A very nice, well executed entry! 7</td>', 'A very nice, well executed entry! 7', '2007-11-14 12:24:34.000000', NULL, 1),
