(4248970, 610589, 63398, '<td valign="top">Very nice. 6</td>', 'Very nice. 6', '2007-11-15 09:14:12.000000', NULL, 1),
(4248981, 612377, 30049, '<td valign="top">I understand your approach...couple of things that stand out for me are;<br/>1) The OOF foreground flower heads seem more like the actual subject than what is behind them.<br/>2) The flower heads still have a very distinctive shape and form to them.  Not really OOF enough to make it complementary bokeh IMO.  Seems more like a mistake (like the flower heads were the intended subject and the focus is just off).<br/> <br/>On a positive note you did a nice job handling exposure overall with good lighting on the foreground area while still keeping the sky and clouds properly exposed.<br/> <br/>Good luck in the challenge.  BTW - no vote, just commenting.  :-)</td>', 'I understand your approach...couple of things that stand out for me are;1) The OOF foreground flower heads seem more like the actual subject than what is behind them.2) The flower heads still have a very distinctive shape and form to them.  Not really OOF enough to make it complementary bokeh IMO.  Seems more like a mistake (like the flower heads were the intended subject and the focus is just off). On a positive note you did a nice job handling exposure overall with good lighting on the foreground area while still keeping the sky and clouds properly exposed. Good luck in the challenge.  BTW - no vote, just commenting.  :-)', '2007-11-15 09:18:44.000000', NULL, 1),
(4248982, 612940, 66414, '<td valign="top">I like the composition of this photo, however the light seems fairly harsh.  Perhaps this would work better at a different time of day or with a filter to tone down the light.</td>', 'I like the composition of this photo, however the light seems fairly harsh.  Perhaps this would work better at a different time of day or with a filter to tone down the light.', '2007-11-15 09:19:11.000000', NULL, 1),
