(4249985, 612604, 811, '<td valign="top">all the different colors and shapes, etc. in the background are a bit distracting.  bw may help to eliminate that and focus the viewer''s eyes even more on the subject.</td>', 'all the different colors and shapes, etc. in the background are a bit distracting.  bw may help to eliminate that and focus the viewer''s eyes even more on the subject.', '2007-11-15 17:15:23.000000', NULL, 1),
(4249986, 612867, 811, '<td valign="top">Good leading lines to the subject, and i like how it is silhoetted.</td>', 'Good leading lines to the subject, and i like how it is silhoetted.', '2007-11-15 17:16:36.000000', NULL, 1),
(4249987, 612921, 811, '<td valign="top">took me a second to see the drop.  good effect -- it gives me a feeling of being infinitely small and powerful.</td>', 'took me a second to see the drop.  good effect -- it gives me a feeling of being infinitely small and powerful.', '2007-11-15 17:17:13.000000', NULL, 1),
(4249989, 611010, 811, '<td valign="top">peek a boo!  a tighter crop would work well too.  the dark candy (I assume) competes for the viewer''s attention with the smiley face.  that can be effective because it gives the viewer somewhere to start, but it can also be distracting.</td>', 'peek a boo!  a tighter crop would work well too.  the dark candy (I assume) competes for the viewer''s attention with the smiley face.  that can be effective because it gives the viewer somewhere to start, but it can also be distracting.', '2007-11-15 17:18:34.000000', NULL, 1),
